#include "stdafx.h"#include "HcdElementBase.h"#include <rsuStr.h>#include <HcdStruct.h>#include <rsuNoNames.h>struct STCPR_P{#include "PrivateVars/TCPR.h"};class KTCPR : public KHcdElementBase  , protected STCPR_P{  char m_szIP[32];  DWORD rdAddresses[16];  DWORD rdDataTypes[16];  DWORD *pAddrw;  DWORD *pDataTypes;//0-float32, 1-unsigned32, 2-signed32, 3-unsigned16, 4-signed16, 5-bit packed, 6-single bit  bool bModbusLinked;  CBase *pRdBases[16];public:  static IHcdElement *Create();protected:  static void InitParm();  virtual int SetProjectValue( LPCSTR pszName, LPCSTR pszValue );  virtual void OnCreated( int domain, LPCSTR pszHmiTagName );  virtual void StepCalc( SStepCalcParams &params );private:  bool LinkModbus();};static KHcdFactory _TCPR("TCPR", KTCPR::Create);IHcdElement *KTCPR::Create(){  return new KTCPR;}//////////////////////////////////////////////////////////////////////////#include "_InitInfo.h"DECLARE_PRIVATE_VARSINFO( KTCPR, 20 )void KTCPR::InitParm(){#include "PrivateVars/TCPR.h"  qsort( s_privateVarInfo, s_kprivateVarInfo, sizeof( SVarInfo ), CompVarInfo );}void KTCPR::OnCreated( int domain, LPCSTR pszHmiTagName ){  if( !s_kprivateVarInfo )    InitParm();  m_kPrivateVarsInfo = s_kprivateVarInfo;  m_pPrivateVarsInfo = s_privateVarInfo;  m_pPrivateObject = (BYTE*)this;}int KTCPR::SetProjectValue( LPCSTR pszName, LPCSTR pszValue ){  int r = -1;  if( !_Kstricmp(pszName,"Address") )  {    if( !pAddrw )      pAddrw = rdAddresses;    else      pAddrw++;    *pAddrw = atoi(pszValue);    r = 0;  }  else if( !_Kstricmp(pszName,"Data Type") )  {    if( !pDataTypes )      pDataTypes = rdDataTypes;    else      pDataTypes++;    *pDataTypes = atoi(pszValue);    r = 0;  }  else    r = __super::SetProjectValue( pszName, pszValue );  return r;}static DWORD s_HCD_IDs[] = { W_ANAVAR::TypeID, W_DIGVAR::TypeID, W_DIGSIG::TypeID, W_ANASIG::TypeID };#include <Winsock2.h>bool KTCPR::LinkModbus(){  if( bModbusLinked )    return true;  if( !INU0 )    return false;  bModbusLinked = true;  in_addr dwIP;  CopyMemory( &dwIP, &INU0, sizeof(dwIP) );  sprintf_s( m_szIP, "%d.%d.%d.%d", dwIP.S_un.S_un_b.s_b4, dwIP.S_un.S_un_b.s_b3, dwIP.S_un.S_un_b.s_b2, dwIP.S_un.S_un_b.s_b1 );  KNoName *pNoname = KMemoryServiceHCD::Instance().GetStructs();  if( !pNoname )    return false;  char szBufName[64] = {};  for( int n=0; n<_countof(rdAddresses); ++n )  {    if( !rdAddresses[n] )      continue;    sprintf_s( szBufName, "%s:0x%X", m_szIP, rdAddresses[n] );    for( int i=0; i<_countof(s_HCD_IDs); ++i )    {      pRdBases[n] = pNoname->FindStruct( szBufName, s_HCD_IDs[i], 0 );      if( !pRdBases[n] )        continue;      break;    }  }  return true;}void KTCPR::StepCalc( SStepCalcParams &params ){  if( !LinkModbus() )    return;  tAnalog32 *pRd = &RD1;  for( int n=0; n<_countof(pRdBases); ++n )  {    if( !pRdBases[n] )      continue;    CBase *p = pRdBases[n];    switch( p->ID_CLASS )    {    case W_ANAVAR::TypeID:      {        W_ANAVAR *v = (W_ANAVAR*)p;        pRd[n] = v->PV;      }      break;    case W_DIGVAR::TypeID:      {        W_DIGVAR *v = (W_DIGVAR*)p;        pRd[n] = v->PV;      }      break;    case W_DIGSIG::TypeID:      {        W_DIGSIG *v = (W_DIGSIG*)p;        pRd[n] = v->PV;      }      break;    case W_ANASIG::TypeID:      {        W_ANASIG *v = (W_ANASIG*)p;        pRd[n] = v->PV;      }      break;    }  }}